<script>
document.querySelectorAll('[data-settings-target]').forEach((tab) => {
  tab.addEventListener('click', () => {
    document.querySelectorAll('[data-settings-target]').forEach((item) => item.classList.toggle('active', item === tab));
    document.querySelectorAll('.settings-section').forEach((section) => {
      section.classList.toggle('active', section.id === `settings-${tab.dataset.settingsTarget}`);
    });
  });
});

document.getElementById('settingsPasswordForm').addEventListener('submit', async (event) => {
  event.preventDefault();
  const form = event.currentTarget;
  const button = document.getElementById('savePasswordButton');
  const body = new FormData(form);
  button.disabled = true;

  try {
    const response = await fetch(form.action, { method: 'POST', body });
    const result = await response.json();
    if (!response.ok || !result.success) throw new Error(result.message || 'Password update failed.');

    form.reset();
    if (window.Swal) await Swal.fire({ icon: 'success', title: 'Password updated', text: result.message });
    else alert(result.message);
  } catch (error) {
    const message = error.message || 'Password update failed. Please try again.';
    if (window.Swal) await Swal.fire({ icon: 'error', title: 'Unable to update password', text: message });
    else alert(message);
  } finally {
    button.disabled = false;
  }
});

