const tablePicker=document.getElementById('documentTablePicker'),tablePickerButton=document.getElementById('insertTableButton'),tablePickerPopover=document.getElementById('documentTablePickerPopover'),tablePickerGrid=document.getElementById('documentTablePickerGrid'),tablePickerSize=document.getElementById('documentTablePickerSize');let hoveredTableRows=0,hoveredTableColumns=0;
function previewTablePicker(rows,columns){hoveredTableRows=rows;hoveredTableColumns=columns;tablePickerSize.textContent=`${columns} columns × ${rows} rows`;tablePickerGrid.querySelectorAll('[data-table-picker-cell]').forEach(cell=>cell.classList.toggle('active',Number(cell.dataset.rows)<=rows&&Number(cell.dataset.columns)<=columns))}
function insertGridTable(rows,columns){restoreSelection();const tableRows=Array.from({length:rows},()=>`<tr>${Array.from({length:columns},()=>'<td><br></td>').join('')}</tr>`).join('');document.execCommand('insertHTML',false,`<table><tbody>${tableRows}</tbody></table><p><br></p>`);rememberSelection();tablePickerPopover.hidden=true;tablePickerButton.setAttribute('aria-expanded','false')}
for(let rows=1;rows<=10;rows++)for(let columns=1;columns<=10;columns++){const cell=document.createElement('button');cell.type='button';cell.className='document-table-picker-cell';cell.dataset.tablePickerCell='1';cell.dataset.rows=String(rows);cell.dataset.columns=String(columns);cell.setAttribute('aria-label',`${columns} columns by ${rows} rows`);cell.addEventListener('pointerenter',()=>previewTablePicker(rows,columns));cell.addEventListener('focus',()=>previewTablePicker(rows,columns));cell.addEventListener('mousedown',event=>event.preventDefault());cell.addEventListener('click',()=>insertGridTable(rows,columns));tablePickerGrid.append(cell)}
tablePickerButton?.addEventListener('mousedown',event=>event.preventDefault());tablePickerButton?.addEventListener('click',()=>{tablePickerPopover.hidden=!tablePickerPopover.hidden;tablePickerButton.setAttribute('aria-expanded',String(!tablePickerPopover.hidden));if(!tablePickerPopover.hidden)previewTablePicker(hoveredTableRows||1,hoveredTableColumns||1)});
