document.getElementById('insertTextButton')?.addEventListener('mousedown',e=>{e.preventDefault();restoreSelection();const editor=activeDocumentEditor,selection=window.getSelection(),range=selection?.rangeCount?selection.getRangeAt(0):null;if(!editor||!range)return;range.deleteContents();const textBox=document.createElement('div');textBox.dataset.freeformText='1';textBox.contentEditable='true';textBox.style.width='240px';textBox.innerText='Click here to type your text.';enableFreeformTextEditing(textBox);range.insertNode(textBox);selectDocumentObject(textBox);textBox.focus();const caret=document.createRange();caret.selectNodeContents(textBox);caret.collapse(false);selection.removeAllRanges();selection.addRange(caret);rememberSelection()});
document.getElementById('insertField')?.addEventListener('change',e=>{const key=e.target.value;if(!key)return;restoreSelection();const labels={document_number:'Document number',page_number:'Page number',total_pages:'Total pages',user:'Request user',requestor_name:'Accountable personnel',form_date:'Date',department:'Department',mobile:'Mobile',address:'Address',email:'Email',employee:'Employee',signature_name:'Signature name',verified_by:'Verified by',approved_by:'Approved by'};document.execCommand('insertHTML',false,`<span data-template-field="${key}">[${labels[key]}]</span>`);e.target.value=''});
