document.querySelector('.document-paper')?.addEventListener('click',e=>{const target=e.target instanceof Element?e.target:null;if(!target)return;const textObject=target.closest('[data-freeform-text="1"]');if(target instanceof HTMLImageElement&&!target.hasAttribute('data-page-background')){selectDocumentObject(target,e.shiftKey);return}if(textObject){selectDocumentObject(textObject,e.shiftKey);if(!e.shiftKey){textObject.focus();rememberSelection()}return}const editable=target.closest('[data-editor]');if(editable){activeDocumentEditor=editable;selectedDocumentImage=null;selectedDocumentObject=null;selectedDocumentObjects=[];imageSelectionBox.style.display='none';rememberSelection();return}if(target.closest('.document-image-selection'))return;selectedDocumentImage=null;selectedDocumentObject=null;selectedDocumentObjects=[];imageSelectionBox.style.display='none';const body=document.querySelector('[data-editor="body_html"]');if(!body)return;activeDocumentEditor=body;body.focus();let range=null;if(document.caretRangeFromPoint)range=document.caretRangeFromPoint(e.clientX,e.clientY);else if(document.caretPositionFromPoint){const position=document.caretPositionFromPoint(e.clientX,e.clientY);if(position){range=document.createRange();range.setStart(position.offsetNode,position.offset);range.collapse(true)}}if(range&&body.contains(range.startContainer)){const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range)}else{const selection=window.getSelection(),end=document.createRange();end.selectNodeContents(body);end.collapse(false);selection.removeAllRanges();selection.addRange(end)}rememberSelection()});
document.getElementById('documentImageFile')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{const source=new Image();source.onload=()=>{const c=document.createElement('canvas');c.width=source.width;c.height=source.height;const context=c.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,c.width,c.height);context.drawImage(source,0,0,c.width,c.height);const editor=activeDocumentEditor;if(!editor)return;if(editor===pageHeader||editor===pageFooter)editor.setAttribute('contenteditable','true');restoreSelection();const selection=window.getSelection(),range=selection?.rangeCount&&editor.contains(selection.getRangeAt(0).startContainer)?selection.getRangeAt(0):null;if(!range)return;range.deleteContents();const img=document.createElement('img'),band=editor===pageHeader||editor===pageFooter,style=band?getComputedStyle(editor):null,availableWidth=band?editor.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight)-4:editor.clientWidth;img.src=c.toDataURL('image/jpeg',.95);img.style.width=band?`${Math.min(c.width,Math.max(48,availableWidth))}px`:'100%';img.style.height='auto';img.setAttribute('draggable','false');range.insertNode(img);selection.removeAllRanges();const after=document.createRange();after.setStartAfter(img);after.collapse(true);selection.addRange(after);rememberSelection();syncPageBandSize(editor,editor===pageFooter);selectDocumentObject(img)};source.src=reader.result};reader.readAsDataURL(f);e.target.value=''});
document.getElementById('imagePageBackground')?.addEventListener('click',()=>{if(!selectedDocumentImage)return;const img=selectedDocumentImage;if(!img.src.startsWith('data:image/jpeg;base64,')){const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const context=c.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,c.width,c.height);context.drawImage(img,0,0,c.width,c.height);img.src=c.toDataURL('image/jpeg',.95)}const body=document.querySelector('[data-editor="body_html"]');if(!img.closest('[data-editor="body_html"]'))body.prepend(img);img.removeAttribute('width');img.removeAttribute('height');img.setAttribute('data-page-background','1');img.removeAttribute('style');selectedDocumentImage=null;selectedDocumentObject=null;selectedDocumentObjects=[];imageSelectionBox.style.display='none';activeDocumentEditor=body});
