[['bringObjectToFront','10'],['sendObjectToBack','0']].forEach(([id,layer])=>{const button=document.getElementById(id);button?.addEventListener('mousedown',event=>event.preventDefault());button?.addEventListener('click',()=>{if(!selectedDocumentObject?.isConnected)return;selectedDocumentObjects.filter(object=>object?.isConnected).forEach(object=>object.style.zIndex=layer);updateSelectedImageWidth();rememberSelection()})});
