documentForm?.addEventListener('submit',async e=>{e.preventDefault();const b=document.getElementById('saveDocumentButton');b.disabled=true;try{document.getElementById('documentFooterHeight').value=String(Math.round(pageFooter.getBoundingClientRect().height));paperEditors.forEach(ed=>document.querySelector(`[data-hidden-editor="${ed.dataset.editor}"]`).value=storedHtml(ed));const r=await fetch(documentForm.action,{method:'POST',body:new FormData(documentForm)});const raw=await r.text();let result;try{result=JSON.parse(raw)}catch{throw new Error(raw.trim().slice(0,300)||`Server returned HTTP ${r.status} without a save response.`)}if(!r.ok||!result.success)throw new Error(result.message||`Unable to save assigned document (HTTP ${r.status}).`);const opt=templateSelect.selectedOptions[0];if(result.template_key&&result.template_key!==opt.dataset.templateKey)throw new Error('The assigned template changed while you were editing. Reload the document and try again.');const t=JSON.parse(opt.dataset.template||'{}');Object.assign(t,{header_text:document.querySelector('[data-hidden-editor="header_text"]').value,body_html:document.querySelector('[data-hidden-editor="body_html"]').value,footer_text:document.querySelector('[data-hidden-editor="footer_text"]').value,footer_height:Number(document.getElementById('documentFooterHeight').value),margin_left:document.querySelector('[data-margin-value="left"]').value,margin_right:document.querySelector('[data-margin-value="right"]').value,margin_top:document.querySelector('[data-margin-value="top"]').value,margin_bottom:document.querySelector('[data-margin-value="bottom"]').value});opt.dataset.template=JSON.stringify(t);if(window.Swal)await Swal.fire({icon:'success',title:'Assigned document saved',text:result.message});else alert(result.message)}catch(err){const m=err.message||'Unable to save assigned document.';if(window.Swal)await Swal.fire({icon:'error',title:'Save failed',text:m});else alert(m)}finally{b.disabled=false}});
